import type { Manifest } from "../schema.js";

/** Caddy serves the preview proxy on :80 inside the tailnet node. */
export function renderCaddyfile(m: Manifest): string {
  const proxied = m.services.filter((s) => s.caddyPath);
  const lines = [
    "# GENERATED by sandboxctl. Do not edit by hand.",
    "{",
    "\tadmin off",
    "}",
    "",
    ":80 {",
    ...proxied.map((s) => `\treverse_proxy localhost:${s.port}`),
    "}",
  ];
  return lines.join("\n") + "\n";
}
